// CSCP held-out mock pool (Phase 3b; decision 3B approved Nov 24, 09:50 ET). 150 original questions, mock only: they never
// appear in lessons, practice, cards or deck progress. Counts per module equal the mock's draw (the deck sizes, which
// follow ASCM's ECM weights), so a held-out run uses every question once. Numbers come from math/supply.js (group mc),
// checked against Python on every build. Practice-exam questions are never copied.
//
// Each item: [lesson, level, stem, right answer, [three wrong options], why, [why not, for each wrong option in order]].
// place() puts the right answer at a position from a fixed cycle, so keys spread evenly over A–D in every module.
'use strict';
const CYCLE = [2, 0, 3, 1, 1, 3, 0, 2, 3, 1, 2, 0, 0, 2, 1, 3];
function place(code, deckBok, items, start) {
  return items.map((it, i) => {
    const [lesson, level, stem, right, wrong, why, whyNot] = it, pos = CYCLE[(i + start) % CYCLE.length];
    const options = wrong.slice(); options.splice(pos, 0, right);
    const wn = {}; let k = 0; for (let j = 0; j < 4; j++) if (j !== pos) wn[j] = whyNot[k++];
    const bok = it[7] || deckBok;
    return { id: 'MK-' + code + '-' + String(i + 1).padStart(2, '0'), lesson, bok, level, status: 'Draft', stem, options, answer: pos, why, whyNot: wn };
  });
}
const B = (l, b) => b;  // readability only

